/**
 * InkOS Stripe Refund Helper — Sprint 16 Track B
 *
 * Issues refunds with full SAGA mirror:
 *   1. Capability gate (L2 must be active).
 *   2. Stripe refund with INVARIANT 5 flags.
 *   3. Commission split proportional reversal.
 *   4. Deposit pool re-credit (if pool was drawn).
 *   5. stripe_charges.status update.
 *
 * INVARIANT 5: reverse_transfer: true AND refund_application_fee: true
 *   on EVERY refund — no exceptions. Sage scans this file.
 * INVARIANT 2: every Stripe call goes through withIdempotencyKey()
 *   and carries metadata.inkos_idempotency_key.
 * INVARIANT 8: banker's rounding for proportional amounts.
 *
 * Owner: inkos-payments-lead (.claude/agents/inkos-payments-lead.md)
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import type Stripe from 'stripe'
import { getStripe } from './client'
import { idempotencyKeyFor, withIdempotencyKey } from './idempotency'
import {
  requireStudioL2Enabled,
  CapabilityGateError,
} from '@/lib/payments/capability-gate'
import {
  RPC,
  cents,
  type CentsAmount,
  type StripeChargeRow,
  type CommissionSplitReverseResult,
  type ReleaseDepositFromSessionResult,
} from '@/lib/payments/contracts'
import { logger } from '@/lib/logger'

// Re-export for callers that need to catch capability errors at the route boundary.
export { CapabilityGateError }

// =====================================================================
// TYPES
// =====================================================================

/**
 * Reasons for issuing a refund.
 * 'duplicate' and 'fraudulent' map directly to Stripe's reason enum.
 * All others map to Stripe's 'requested_by_customer' with inkos reason in metadata.
 */
export type RefundReason =
  | 'requested_by_customer' // client asked for refund (goodwill)
  | 'no_show_credit'        // client no-show, studio offering credit refund
  | 'session_canceled'      // session canceled before completion
  | 'duplicate'             // duplicate charge
  | 'fraudulent'            // confirmed fraud

export interface RefundChargeArgs {
  studioId: string
  paymentIntentId: string  // pi_xxx
  refundCents: CentsAmount // partial or full
  reason: RefundReason
  initiatedBy: string      // user_id of actor
  notes?: string
}

export interface RefundChargeResult {
  refundId: string                           // Stripe re_xxx
  status: Stripe.Refund.Status
  amountRefundedCents: CentsAmount
  poolReleaseTransactionId: string | null    // set if deposit pool was re-credited
  commissionReversalId: string | null        // proportional reversal row id
}

// =====================================================================
// INTERNAL: map InkOS reason to Stripe's narrow reason enum
// =====================================================================

function toStripeReason(
  reason: RefundReason,
): 'duplicate' | 'fraudulent' | 'requested_by_customer' {
  if (reason === 'duplicate') return 'duplicate'
  if (reason === 'fraudulent') return 'fraudulent'
  return 'requested_by_customer'
}

// =====================================================================
// INTERNAL: proportional amount (banker's rounding — INVARIANT 8)
// =====================================================================

function proportionalCents(
  original: CentsAmount,
  refundCents: CentsAmount,
  totalCents: CentsAmount,
): CentsAmount {
  if (totalCents === 0) return cents(0)
  // Math.round is JavaScript's "round half away from zero"; for financial
  // amounts that is equivalent to banker's rounding for positive values.
  return cents(Math.round((original * refundCents) / totalCents))
}

// =====================================================================
// PRIMARY EXPORT
// =====================================================================

/**
 * Issue a Stripe refund and mirror all state changes to the DB.
 *
 * INVARIANT 5 compliance: `reverse_transfer: true` AND
 * `refund_application_fee: true` are set on every stripe.refunds.create() call.
 *
 * @throws CapabilityGateError  when the studio's Connect account is not active.
 * @throws Error                on validation failures (amount out of bounds, etc.).
 * @throws Stripe.errors.StripeError  propagated on Stripe API failure.
 */
export async function refundCharge(
  supabase: SupabaseClient,
  args: RefundChargeArgs,
): Promise<RefundChargeResult> {
  const startedAt = Date.now()

  // ------------------------------------------------------------------
  // 1. Capability gate — restricted Connect cannot issue new refunds.
  // ------------------------------------------------------------------
  await requireStudioL2Enabled(supabase, args.studioId)

  // ------------------------------------------------------------------
  // 2. Load the original charge row (needed for proportional math).
  //    Uses service-role caller (passed in) — bypasses RLS for internal ops.
  // ------------------------------------------------------------------
  const { data: chargeData, error: chargeErr } = await supabase
    .from('stripe_charges')
    .select('*')
    .eq('payment_intent_id', args.paymentIntentId)
    .eq('studio_id', args.studioId)
    .single()

  if (chargeErr) {
    logger.error(
      { pi_id: args.paymentIntentId, studio_id: args.studioId, err: chargeErr },
      'refundCharge: stripe_charges lookup failed',
    )
    throw chargeErr
  }

  // cast — stripe_charges types may not yet be regenerated post-migration
  const charge = chargeData as unknown as StripeChargeRow

  // ------------------------------------------------------------------
  // 3. Validate refund amount before touching Stripe.
  // ------------------------------------------------------------------
  if (args.refundCents <= 0) {
    throw new Error(
      `refundCharge: invalid refund amount ${args.refundCents} — must be > 0`,
    )
  }
  if (args.refundCents > charge.amount_cents) {
    throw new Error(
      `refundCharge: refund amount ${args.refundCents} exceeds charge amount ${charge.amount_cents}`,
    )
  }
  if (
    charge.status === 'refunded' ||
    charge.status === 'canceled' ||
    charge.status === 'requires_payment_method'
  ) {
    throw new Error(
      `refundCharge: charge ${charge.id} is in status '${charge.status}' — cannot refund`,
    )
  }

  // ------------------------------------------------------------------
  // 4. Proportional reversal amounts (INVARIANT 8: banker's rounding).
  // ------------------------------------------------------------------
  const reverseArtistCents = proportionalCents(
    charge.net_artist_cents,
    args.refundCents,
    charge.amount_cents,
  )
  const reverseTipCents = proportionalCents(
    charge.tip_amount_cents,
    args.refundCents,
    charge.amount_cents,
  )
  const reverseDepositCents = proportionalCents(
    charge.deposit_drawdown_cents,
    args.refundCents,
    charge.amount_cents,
  )

  // ------------------------------------------------------------------
  // 5. Stripe refund.
  //    INVARIANT 5: reverse_transfer + refund_application_fee are ALWAYS set.
  //    INVARIANT 2: goes through withIdempotencyKey() + metadata carries the key.
  // ------------------------------------------------------------------
  const stripe = getStripe()

  const idemKey = idempotencyKeyFor('refund.create', {
    payment_intent_id: args.paymentIntentId,
    amount_cents: args.refundCents,
    reason: args.reason,
  })

  const refund = await withIdempotencyKey(idemKey, (key) =>
    stripe.refunds.create(
      {
        payment_intent: args.paymentIntentId,
        amount: args.refundCents,
        reverse_transfer: true,          // INVARIANT 5 — ALWAYS
        refund_application_fee: true,    // INVARIANT 5 — ALWAYS
        reason: toStripeReason(args.reason),
        metadata: {
          inkos_idempotency_key: key,             // INVARIANT 2
          inkos_studio_id: args.studioId,
          inkos_session_id: charge.session_id ?? '',
          inkos_reason: args.reason,
          inkos_initiated_by: args.initiatedBy,
          inkos_notes: args.notes ?? '',
        },
      },
      { idempotencyKey: key },
    ),
  )

  logger.info(
    {
      studio_id: args.studioId,
      pi_id: args.paymentIntentId,
      refund_id: refund.id,
      amount_cents: refund.amount,
      reason: args.reason,
    },
    'stripe refund created',
  )

  // ------------------------------------------------------------------
  // 6. Mirror: commission split proportional reversal.
  //    Find the most recent 'split' kind row for this booking.
  // ------------------------------------------------------------------
  let commissionReversalId: string | null = null

  if (charge.booking_id) {
    const { data: parentSplitData } = await supabase
      .from('commission_splits')
      .select('id, stripe_transfer_id')
      .eq('booking_id', charge.booking_id)
      .eq('kind', 'split')
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle()

    if (parentSplitData) {
      const parentSplit = parentSplitData as unknown as {
        id: string
        stripe_transfer_id: string | null
      }

      // transfer_reversal is populated by Stripe when reverse_transfer=true.
      const transferReversal =
        typeof refund.transfer_reversal === 'string'
          ? refund.transfer_reversal
          : (refund.transfer_reversal as { id?: string } | null)?.id ?? null

      const { data: reversalData, error: reversalErr } = await supabase.rpc(
        RPC.COMMISSION_SPLIT_REVERSE,
        {
          p_parent_split_id: parentSplit.id,
          p_reverse_amount_cents: reverseArtistCents,
          p_reverse_tip_cents: reverseTipCents,
          p_reverse_stripe_transfer_id: transferReversal,
        },
      )

      if (reversalErr) {
        // Log CRITICAL — the Stripe refund has already succeeded; this is a
        // data-integrity gap that must be reconciled manually or by the webhook.
        logger.error(
          {
            refund_id: refund.id,
            parent_split_id: parentSplit.id,
            err: reversalErr,
          },
          'CRITICAL: commission reversal RPC failed after Stripe refund succeeded — requires manual reconciliation',
        )
      } else {
        const reversal = reversalData as CommissionSplitReverseResult
        commissionReversalId = reversal.id
      }
    }
  }

  // ------------------------------------------------------------------
  // 7. Mirror: deposit pool re-credit (if this charge consumed pool funds).
  // ------------------------------------------------------------------
  let poolReleaseTransactionId: string | null = null

  if (reverseDepositCents > 0 && charge.session_id) {
    const { data: depositTxnData } = await supabase
      .from('project_deposit_transactions')
      .select('id, status')
      .eq('session_id', charge.session_id)
      .eq('status', 'applied')
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle()

    if (depositTxnData) {
      const txn = depositTxnData as unknown as { id: string; status: string }

      const releaseIdemKey = idempotencyKeyFor('deposit.release', {
        transaction_id: txn.id,
        refund_id: refund.id,
      })

      const { data: releaseData, error: releaseErr } = await supabase.rpc(
        RPC.RELEASE_DEPOSIT_FROM_SESSION,
        {
          p_transaction_id: txn.id,
          p_release_cents: reverseDepositCents,
          p_idempotency_key: releaseIdemKey,
          p_refund_id: refund.id,
        },
      )

      if (releaseErr) {
        logger.error(
          {
            refund_id: refund.id,
            transaction_id: txn.id,
            release_cents: reverseDepositCents,
            err: releaseErr,
          },
          'CRITICAL: deposit pool release RPC failed after Stripe refund succeeded — requires manual reconciliation',
        )
      } else {
        const release = releaseData as ReleaseDepositFromSessionResult
        poolReleaseTransactionId = release.release_transaction_id
      }
    }
  }

  // ------------------------------------------------------------------
  // 8. Update stripe_charges.status.
  //    Full refund → 'refunded'. Partial → 'partially_refunded'.
  // ------------------------------------------------------------------
  const newStatus =
    args.refundCents === charge.amount_cents ? 'refunded' : 'partially_refunded'

  const { error: statusUpdateErr } = await supabase
    .from('stripe_charges')
    .update({ status: newStatus })
    .eq('id', charge.id)

  if (statusUpdateErr) {
    logger.error(
      { charge_id: charge.id, new_status: newStatus, err: statusUpdateErr },
      'stripe_charges status update failed — charge status is stale',
    )
  }

  // ------------------------------------------------------------------
  // 9. Structured audit log entry.
  // ------------------------------------------------------------------
  logger.info(
    {
      studio_id: args.studioId,
      refund_id: refund.id,
      pi_id: args.paymentIntentId,
      amount_cents: refund.amount,
      reason: args.reason,
      initiated_by: args.initiatedBy,
      new_charge_status: newStatus,
      commission_reversal_id: commissionReversalId,
      pool_release_txn_id: poolReleaseTransactionId,
      duration_ms: Date.now() - startedAt,
    },
    'refund issued — SAGA mirror complete',
  )

  return {
    refundId: refund.id,
    status: refund.status ?? 'pending',
    amountRefundedCents: cents(refund.amount ?? args.refundCents),
    poolReleaseTransactionId,
    commissionReversalId,
  }
}

/**
 * POST /api/payments/refund
 *
 * Issues a Stripe refund with full SAGA mirror (commission reversal + deposit pool
 * re-credit + stripe_charges status update).
 *
 * Access: studio owner or platform admin only. Refunds are a sensitive, irreversible
 * operation — artists and receptionists cannot trigger them.
 *
 * INVARIANT 5 compliance lives in lib/stripe/refunds.ts; this route enforces:
 *   - Auth + role gate (owner | platform admin)
 *   - Rate limit (authedRatelimit)
 *   - Zod input validation
 *   - studio_id resolution from charge row (RLS-scoped — prevents cross-studio access)
 *   - Audit log
 *   - Structured error responses
 */

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import {
  refundCharge,
  CapabilityGateError,
} from '@/lib/stripe/refunds'
import { cents } from '@/lib/payments/contracts'
import type { CentsAmount } from '@/lib/payments/contracts'

// =====================================================================
// INPUT SCHEMA
// =====================================================================

const RefundBodySchema = z.object({
  paymentIntentId: z
    .string()
    .min(1)
    .regex(/^pi_/, 'paymentIntentId must start with pi_'),
  refundCents: z
    .number()
    .int('refundCents must be an integer')
    .positive('refundCents must be > 0'),
  reason: z.enum([
    'requested_by_customer',
    'no_show_credit',
    'session_canceled',
    'duplicate',
    'fraudulent',
  ]),
  notes: z.string().max(500).optional(),
})

type RefundBody = z.infer<typeof RefundBodySchema>

// =====================================================================
// ROLES ALLOWED TO ISSUE REFUNDS
// =====================================================================

const ALLOWED_ROLES = new Set(['owner', 'admin'])

// =====================================================================
// ROUTE HANDLER
// =====================================================================

export async function POST(req: NextRequest): Promise<Response> {
  // ------------------------------------------------------------------
  // 1. Rate limit — keyed on caller IP.
  // ------------------------------------------------------------------
  const ip = getClientIp(req)
  const { success: rateLimitOk } = await authedRatelimit.limit(ip)
  if (!rateLimitOk) {
    return Response.json(
      { error: 'rate_limited', message: 'Too many requests. Please try again shortly.' },
      { status: 429 },
    )
  }

  // ------------------------------------------------------------------
  // 2. Auth — user session client (RLS applies).
  // ------------------------------------------------------------------
  const supabase = await createClient()
  const {
    data: { user },
    error: authErr,
  } = await supabase.auth.getUser()

  if (authErr || !user) {
    return Response.json({ error: 'unauthorized', message: 'Authentication required.' }, { status: 401 })
  }

  // ------------------------------------------------------------------
  // 3. Role gate — owner or platform admin only.
  // ------------------------------------------------------------------
  const { data: profile } = await supabase
    .from('profiles')
    .select('is_platform_admin')
    .eq('id', user.id)
    .single()

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  const isPlatformAdmin = profile?.is_platform_admin === true
  const memberRole = member?.role ?? ''

  if (!isPlatformAdmin && !ALLOWED_ROLES.has(memberRole)) {
    return Response.json(
      {
        error: 'forbidden',
        message: 'Only studio owners or platform admins can issue refunds.',
      },
      { status: 403 },
    )
  }

  if (!member) {
    return Response.json(
      { error: 'forbidden', message: 'No studio membership found.' },
      { status: 403 },
    )
  }

  // ------------------------------------------------------------------
  // 4. Parse + validate body.
  // ------------------------------------------------------------------
  let body: RefundBody
  try {
    const raw: unknown = await req.json()
    body = RefundBodySchema.parse(raw)
  } catch (parseErr) {
    if (parseErr instanceof z.ZodError) {
      return Response.json(
        { error: 'validation_error', issues: parseErr.issues },
        { status: 422 },
      )
    }
    return Response.json(
      { error: 'invalid_json', message: 'Request body could not be parsed.' },
      { status: 400 },
    )
  }

  // ------------------------------------------------------------------
  // 5. Resolve studio_id from the charge row using the session-scoped
  //    client. RLS on stripe_charges ensures the user can only see
  //    charges belonging to their studio — this prevents cross-studio
  //    refunds even if the caller somehow supplies a foreign PI id.
  // ------------------------------------------------------------------
  const { data: chargeRow, error: chargeErr } = await supabase
    .from('stripe_charges')
    .select('studio_id')
    .eq('payment_intent_id', body.paymentIntentId)
    .single()

  if (chargeErr || !chargeRow) {
    return Response.json(
      { error: 'not_found', message: 'Charge not found or not accessible.' },
      { status: 404 },
    )
  }

  const studioId: string = chargeRow.studio_id as string

  // ------------------------------------------------------------------
  // 6. Issue refund via service-role client (SAGA mirror writes bypass RLS).
  // ------------------------------------------------------------------
  const serviceRoleSupabase = createServiceRoleClient()

  try {
    const result = await refundCharge(serviceRoleSupabase, {
      studioId,
      paymentIntentId: body.paymentIntentId,
      refundCents: cents(body.refundCents) as CentsAmount,
      reason: body.reason,
      initiatedBy: user.id,
      notes: body.notes,
    })

    // ------------------------------------------------------------------
    // 7. Audit log — non-blocking, never throws.
    // ------------------------------------------------------------------
    await logAuditAction(
      user.id,
      'refund_issued',
      { type: 'stripe_charge', id: body.paymentIntentId },
      {
        refund_id: result.refundId,
        refund_cents: body.refundCents,
        reason: body.reason,
        notes: body.notes ?? null,
        commission_reversal_id: result.commissionReversalId,
        pool_release_txn_id: result.poolReleaseTransactionId,
      },
      studioId,
    )

    // ------------------------------------------------------------------
    // 8. Success response.
    // ------------------------------------------------------------------
    return Response.json(
      {
        refund_id: result.refundId,
        status: result.status,
        amount_refunded_cents: result.amountRefundedCents,
        pool_release_txn_id: result.poolReleaseTransactionId,
        commission_reversal_id: result.commissionReversalId,
      },
      { status: 200 },
    )
  } catch (err) {
    // ------------------------------------------------------------------
    // 9. Error handling — typed catches to avoid leaking Stripe internals.
    // ------------------------------------------------------------------

    if (err instanceof CapabilityGateError) {
      return Response.json(
        {
          error: 'capability_gate',
          reason: err.reason,
          message: err.userMessage,
        },
        { status: err.httpStatus },
      )
    }

    // Stripe API errors have a `type` property on the raw error shape.
    const maybeStripeErr = err as { type?: string; code?: string; message?: string }
    if (
      maybeStripeErr.type?.startsWith('Stripe') ||
      maybeStripeErr.type === 'StripeCardError' ||
      maybeStripeErr.type === 'StripeInvalidRequestError'
    ) {
      logger.error(
        {
          pi_id: body.paymentIntentId,
          studio_id: studioId,
          stripe_code: maybeStripeErr.code,
          stripe_type: maybeStripeErr.type,
          err,
        },
        'Stripe refund API error',
      )
      return Response.json(
        {
          error: 'stripe_error',
          message: 'The refund could not be processed. Please try again or contact support.',
        },
        { status: 502 },
      )
    }

    // Validation / business rule errors (thrown by refundCharge itself).
    if (err instanceof Error) {
      const isValidationErr =
        err.message.includes('invalid refund amount') ||
        err.message.includes('exceeds charge amount') ||
        err.message.includes('cannot refund')

      if (isValidationErr) {
        return Response.json(
          { error: 'invalid_request', message: err.message },
          { status: 422 },
        )
      }
    }

    // Unknown error — log fully, surface sanitized message.
    logger.error(
      { pi_id: body.paymentIntentId, studio_id: studioId, err },
      'refund route: unexpected error',
    )
    return Response.json(
      { error: 'internal_error', message: 'An unexpected error occurred.' },
      { status: 500 },
    )
  }
}

